  "Typical Spec": { en: "Typical Spec", hi: "सामान्य स्पेसिफिसिटी", mr: "सामान्य स्पेसिफिसिटी", ta: "வழக்கமான தன்மை", te: "సాధారణ స్పెసిఫిసిటీ", bn: "স্বাভাবিক স্পেসিফিসিটি", gu: "સામાન્ય સ્પેસિફિસિટી", kn: "ಸಾಮಾನ್ಯ ಸ್ಪೆಸಿಫಿಸಿಟಿ" },
