  "Refer specificity": { en: "Refer specificity", hi: "रेफर विशिष्टता", mr: "रेफर विशिष्टता", ta: "பரிந்துரை தன்மை", te: "రెఫర్ స్పెసిఫిసిటీ", bn: "রেফার স্পেসিফিসিটি", gu: "રેફર સ્પેસિફિસિટી", kn: "ರೆಫರ್ ಸ್ಪೆಸಿಫಿಸಿಟಿ" },
